#!/usr/bin/env bash
# seq2cause-bench — the context family's PER-TRACE ROOT-CAUSE AXIS on xs, s and m (seeds 0–4) on one GPU box; generated
# 2026-11-06 from the landed per-trace job rca-trace-axis-26-10-31.sh (the box form) and the s / m case-level job
# rca-ctx-s-m-26-11-06.sh (the probe layouts from each seed's context freeze). plans/rca-arms.md addendum "2026-10-31,
# later" (D-TBR-16 … 19; "Environment, cost, staging": the per-trace probes of the five context arms run on the GPU
# replica of D-TBR-15's class, three layouts, ≈ 1.1 M traces per core layout over xs / s / m). Per corpus xs → s → m:
# pull (tier rca, from the public dataset host) → export (asserted equal, case by case, to the landed export-trace
# record) → per probe layout (core overwrite = the information-gain and CMI cells of one forward; core keep = the two
# keep cells; atomic CMI keep) one ranktrace per arm with --axis trace --select post-nonok --cap 0 (rule R, every
# failed request trace wholly inside the fault window, no cap; the first arm of a layout probes, the others re-rank
# the shared --work-dir, `runner_reused`); the trace axis writes every reading per probed trace (hop1, hop0 and the
# source rule; --reading hop0 names the primary, the registered primary on both axes) → control/trace-earliest per
# trace (D-TBR-19; scored through scoretrace --rows arm-only) → the raw shards deleted. The probe layouts come from
# the committed context freezes (2026-11-01): the two overwrite arms share one forward except on s seeds 2 and 4,
# where the CMI cell froze at c = 2 and the two are probed separately (4 probes on those corpora, 3 elsewhere);
# the keep arms share one forward on every corpus (c = 1, every position tested); the atomic CMI arm is its own.
# Staging: xs smallest-rung; every s row names the xs rank-trace record of the same arm made earlier in this chain,
# every m row the s record (form record, as the landed per-trace job). Probes on the A10G (--device cuda): a
# disclosed GPU replica of the frozen cells — the tolerance check of D-TBR-15 is not applicable (no landed CPU row
# of these cells). Backbones are input artifacts (input/<rung>-s<k>/model), hash-checked against the freezes.
# Scoring (tracebenchrca.scoretrace, B = 2000, seed 0) and the landing run locally. Last line: the sibling's
# artifacts manifest (the provisioning's own manifest step names the reference harness's package).
# One command per line (scripts/tfvars_check.py parses every tracebenchrca command with the real parsers); the
# runner's cwd is benchmarks/trace-bench-rca; set -e stops at the first failure so a half-run never masquerades as a run.
set -euo pipefail
TP=$HOME/miniforge3/envs/seq2cause-trace-bench/bin/python
HR=../..
L=../trace-bench/plans/staging-ledger.json

python -m tracebenchrca.pull --repo chadyuk/trace-bench --revision v0.3.0 --rung xs --variant latent --seed 0 --tier rca --dest corpora --output-folder out/rca-ctx-trace/xs-s0/pull-rca-ctx-trace
python -m tracebenchrca.export --corpus-dir corpora/instances/xs/latent/seed=0 --rung xs --out exports/xs-s0 --workers 4 --extras --expect-cases results/xs/latent/seed=0/export-trace/run/results.json --output-folder out/rca-ctx-trace/xs-s0/export-ctx-trace
python -m tracebenchrca.ranktrace --arm rca/trace-ig-overwrite --probe-arms rca/trace-ig-overwrite rca/trace-cmi-overwrite --reading hop0 --phase post --subtract none --pre-record none --axis trace --select post-nonok --cap 0 --export-record out/rca-ctx-trace/xs-s0/export-ctx-trace --corpus-dir corpora/instances/xs/latent/seed=0 --model-dir input/xs-s0/model --freeze ../trace-bench/freezes/2026-11-01-xs-latent-s0-context.json --rung xs --seed 0 --trace-python $TP --harness-root $HR --device cuda --work-dir out/rca-ctx-trace/work/xs-s0-core-ow --prior-rung-record smallest-rung --staging-ledger $L --output-folder out/rca-ctx-trace/xs-s0/rca-trace-ig-overwrite/trace/rank
